function MsgHeading({ title, para }) {
  return (
    <div className=" flex justify-  ">
      <div className=" text-yellow-400 text-xl bg-red-500   ">{title} : </div>
      <p className=""> {para}</p>
    </div>
  );
}

export default MsgHeading;
